#include <bits/stdc++.h>
using namespace std;

int main() {
ios::sync_with_stdio(false);
cin.tie(nullptr);
int t;
cin>>t;
cout<<endl;
while(t--){
int n; 
cin>>n;
int arr[n];
int maxdiff = INT_MIN;
int maxdiff1 = INT_MIN;
int pos = 0;
vector<int> x;
for(int i = 0;i<n;i++){
cin>>arr[i];
if(i>=1){
    if(arr[i]-arr[i-1]>maxdiff){
    maxdiff = arr[i]-arr[i-1];
    if(maxdiff<0)maxdiff = -maxdiff;
    pos = i;
    }
}
}

   for(int i = pos;i<n;i++){
        x.push_back(arr[i]);
    }
     for(int i = 0;i<pos;i++){
          x.push_back(arr[i]);
     }
    for(int i =1;i<n;i++){
        //cout<<x[i]<<endl;
        if(x[i]-x[i-1] > 0){
        maxdiff1 = max(maxdiff1, x[i]-x[i-1]);
        }
        else {
            maxdiff1 = max(maxdiff1, -x[i]+x[i-1]);
        }
    }
int ans = min(maxdiff,maxdiff1);
cout<<ans<<endl;
}
}
